import org.springframework.web.bind.annotation.PathVariable;

/** Reopen the named closed or soft-closed period, dropping its fixed due-total so it is live again. Refused when the user's role may
 *  not reopen (the sheet's permission matrix; by default a steward only), there is no such period, or it is neither closed nor soft-closed. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            @Val PeriodCloseInput input, PeriodRepository periods, RoleRepository roles, SettingRepository settings,
            Out<Period> reopened) throws InvalidPeriodException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        if (!settings.permissions(id).allows("reopen", roles.of(id, input.user()))) {
            throw new InvalidPeriodException("Your role may not reopen a period on this sheet.");
        }
        Period period = periods.find(id, periodName);
        if (period == null) {
            throw new InvalidPeriodException("There is no period " + periodName.trim() + " on this sheet.");
        }
        if (!(period.closed() || period.soft()) || !periods.reopen(period)) {
            throw new InvalidPeriodException("The period " + period.name() + " is not closed.");
        }
        reopened.set(new Period(period.sheetId(), period.name(), period.from(), period.to(), false, null, false, period.cap()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's period: a name unique on the sheet and an inclusive from and to date; whether it is closed, and
 *  the due-total fixed when it was closed (null while open); and whether it is soft-closed: its due-total (and each
 *  person's) fixed as a close fixes them, while its claims can still be changed (never both closed and soft); and the
 *  most OPEN or PENDING claims a person may have in it (null: no cap). */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft, Integer cap) {

    /** Whether this period shares a day with the dates from..to (inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }

    /** Whether the date falls in this period. */
    public boolean contains(LocalDate date) {
        return overlaps(date, date);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;
import java.util.TreeMap;

/** A period as the screen shows it: the name, the from and to dates (yyyy-mm-dd), whether it is closed, the
 *  due-total fixed when it was closed (null while open), and each person's due-total fixed then, by person id
 *  (empty while open), and whether it is soft-closed (its figures fixed as for a closed one), and its cap on each person's OPEN or PENDING claims (null: none). */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<Long, String> personTotals, boolean soft, Integer cap) {
