        jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, person.id());
    }
    jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.id());
    alias(into, person.name());
}

